    47  /*
    48   * Removes the port from the host header
    49   */
    50  int flb_http_strip_port_from_host(struct flb_http_client *c)
    51  {
    52      struct mk_list *head;
    53      struct flb_kv *kv;
    54      char *out_host;
    55      struct flb_upstream *u = c->u_conn->u;
    56
    57      if (!c->host) {
    58          out_host = u->tcp_host;
    59      } else {
    60          out_host = (char *) c->host;
    61      }
    62
    63      mk_list_foreach(head, &c->headers) {
    64          kv = mk_list_entry(head, struct flb_kv, _head);
    65          if (strcasecmp("Host", kv->key) == 0) {
    66              flb_sds_destroy(kv->val);
    67              kv->val = NULL;
    68              kv->val = flb_sds_create(out_host);
    69              if (!kv->val) {
    70                  flb_errno();
    71                  return -1;
    72              }
    73              return 0;
    74          }
    75      }
    76
    77      return -1;
    78  }
