    90  /* check if there is enough space in the client header buffer */
    91  static int header_available(struct flb_http_client *c, int bytes)
    92  {
    93      int available;
    94
    95      available = c->header_size - c->header_len;
    96      if (available < bytes) {
    97          return -1;
    98      }
    99
   100      return 0;
   101  }
