   103  /* Try to find a header value in the buffer */
   104  static int header_lookup(struct flb_http_client *c,
   105                           const char *header, int header_len,
   106                           const char **out_val, int *out_len)
   107  {
   108      char *p;
   109      char *crlf;
   110      char *end;
   111
   112      /* Lookup the beginning of the header */
   113      p = strcasestr(c->resp.data, header);
   114      end = strstr(c->resp.data, "\r\n\r\n");
   115      if (!p) {
   116          if (end) {
   117              /* The headers are complete but the header is not there */
   118              return FLB_HTTP_NOT_FOUND;
   119          }
   120
   121          /* We need more data */
   122          return FLB_HTTP_MORE;
   123      }
   124
   125      /* Exclude matches in the body */
   126      if (end && p > end) {
   127          return FLB_HTTP_NOT_FOUND;
   128      }
   129
   130      /* Lookup CRLF (end of line \r\n) */
   131      crlf = strstr(p, "\r\n");
   132      if (!crlf) {
   133          return FLB_HTTP_MORE;
   134      }
   135
   136      p += header_len;
   137
   138      *out_val = p;
   139      *out_len = (crlf - p);
   140
   141      return FLB_HTTP_OK;
   142  }
