   144  /* HTTP/1.1: Check if we have a Chunked Transfer Encoding */
   145  static int check_chunked_encoding(struct flb_http_client *c)
   146  {
   147      int ret;
   148      int len;
   149      const char *header = NULL;
   150
   151      ret = header_lookup(c, "Transfer-Encoding: ", 19,
   152                          &header, &len);
   153      if (ret == FLB_HTTP_NOT_FOUND) {
   154          /* If the header is missing, this is fine */
   155          c->resp.chunked_encoding = FLB_FALSE;
   156          return FLB_HTTP_OK;
   157      }
   158      else if (ret == FLB_HTTP_MORE) {
   159          return FLB_HTTP_MORE;
   160      }
   161
   162      if (strncasecmp(header, "chunked", len) == 0) {
   163          c->resp.chunked_encoding = FLB_TRUE;
   164      }
   165
   166      return FLB_HTTP_OK;
   167  }
