   169  /* Check response for a 'Content-Length' header */
   170  static int check_content_length(struct flb_http_client *c)
   171  {
   172      int ret;
   173      int len;
   174      const char *header;
   175      char tmp[256];
   176
   177      if (c->resp.status == 204) {
   178          c->resp.content_length = -1;
   179          return FLB_HTTP_OK;
   180      }
   181
   182      ret = header_lookup(c, "Content-Length: ", 16,
   183                          &header, &len);
   184      if (ret == FLB_HTTP_MORE) {
   185          return FLB_HTTP_MORE;
   186      }
   187      else if (ret == FLB_HTTP_NOT_FOUND) {
   188          return FLB_HTTP_NOT_FOUND;
   189      }
   190
   191      if (len > sizeof(tmp) - 1) {
   192          /* Value too long */
   193          return FLB_HTTP_ERROR;
   194      }
   195
   196      /* Copy to temporary buffer */
   197      memcpy(tmp, header, len);
   198      tmp[len] = '\0';
   199
   200      c->resp.content_length = atoi(tmp);
   201      return FLB_HTTP_OK;
   202  }
